content:
{
  "root_cause": "The Awesomplete library assigns tabindex='0' to each suggestion list item, making them focusable and causing the Tab key to move focus into the list instead of skipping to the next form field.",
  "repair_strategy": "Change the tabindex attribute of list items from '0' to '-1' so they are removed from the tab order, allowing Tab to navigate from the combobox to the next field while preserving arrow-key navigation and screen reader support via aria-activedescendant.",
  "edits": [
    {
      "path": "awesomplete.js",
      "sha256": "b60dd8ec51ae96e979d58de3e9681449056b74a3d44031eb1121f325bc2e3af6",
      "before": "_.ITEM = function (text, input, item_id) {\n\tvar html = input.trim() === \"\" ? text : text.replace(RegExp($.regExpEscape(input.trim()), \"gi\"), \"<mark>$&</mark>\");\n\treturn $.create(\"li\", {\n\t\tinnerHTML: html,\n\t\t\"role\": \"option\",\n\t\t\"aria-selected\": \"false\",\n\t\t\"tabindex\": '0', // for the Talkback screen reader\n\t\t\"id\": \"awesomplete_list_\" + this.count + \"_item_\" + item_id\n\t});\n}\n",
      "after": "_.ITEM = function (text, input, item_id) {\n\tvar html = input.trim() === \"\" ? text : text.replace(RegExp($.regExpEscape(input.trim()), \"gi\"), \"<mark>$&</mark>\");\n\treturn $.create(\"li\", {\n\t\tinnerHTML: html,\n\t\t\"role\": \"option\",\n\t\t\"aria-selected\": \"false\",\n\t\t\"tabindex\": '-1', // for the Talkback screen reader\n\t\t\"id\": \"awesomplete_list_\" + this.count + \"_item_\" + item_id\n\t});\n}\n"
    }
  ],
  "expected_accessibility_effect": "Tab key will move focus from the city combobox to the dietary requirements field when the suggestion list is open, satisfying WCAG 2.1.1 keyboard accessibility and 2.4.3 focus order.",
  "functional_risks": [
    "Talkback screen reader users may lose ability to tab into suggestion items; however, arrow key navigation and aria-activedescendant should still convey selection and movement."
  ],
  "verification_requirements": [
    "After typing 'Ber' in the city field and pressing Tab, focus must shift to the dietary requirements input.",
    "ArrowUp and ArrowDown keys must still change the highlighted suggestion and update aria-activedescendant.",
    "Enter key must still select the highlighted suggestion and close the list.",
    "The suggestion list must remain readable by screen readers via aria-activedescendant."
  ]
}
